/// <reference lib="dom" />
/// <reference lib="dom.iterable" />
/// <reference lib="es2023" />

import {
  type ComponentProps,
  createContext,
  type CSSProperties,
  forwardRef,
  type ReactNode,
  useContext,
  useId,
} from "react";
import {
  AbsoluteFill,
  Easing,
  getRemotionEnvironment,
  Interactive,
  type InteractivitySchema,
  interpolate,
  Sequence,
  useCurrentFrame,
  useVideoConfig,
} from "remotion";
import { converter, formatRgb, parse, type Rgb } from "culori";

interface KitTheme {
  background: string;
  foreground: string;
  card: string;
  cardForeground: string;
  popover: string;
  popoverForeground: string;
  primary: string;
  primaryForeground: string;
  secondary: string;
  secondaryForeground: string;
  muted: string;
  mutedForeground: string;
  accent: string;
  accentForeground: string;
  destructive: string;
  destructiveForeground: string;
  border: string;
  input: string;
  ring: string;
  radius: number;
  /**
   * The face every text component paints with, as a label from `fonts.ts` or a
   * CSS family the caller has loaded themselves.
   *
   * Optional and defaulted to nothing on purpose: unset, each component keeps
   * the face it was designed around, so adding this token changed no existing
   * render. Set it on `KitUIProvider` and one value re-skins a whole
   * timeline — which is the only reason it lives on the theme rather than
   * staying a per-component prop.
   */
  fontFamily?: string;
}

/**
 * The shadcn token set, as concrete values.
 *
 * ## These are a mirror of `app/globals.css`, and that is the whole point
 *
 * A component we ship lands next to somebody's `Button` and `Input`, and those
 * paint from the CSS custom properties in `globals.css`. A scene that paints
 * from a *different* set of greys is a scene that clashes with the app it was
 * installed into — which is exactly what happened here: this file was written
 * first, `globals.css` was later re-skinned warm, and for a while the site and
 * the videos it sells were two different products.
 *
 * So every value below is the **literal string** from the corresponding
 * `--token` in `app/globals.css` (`:root` for light, `.dark` for dark). Hex, not
 * oklch, purely so that drift is a string comparison — if the two files ever
 * disagree again, `pnpm run check:tokens` says so and prints the pairs.
 *
 * ## Why not just read `var(--token)`?
 *
 * Because a Remotion bundle has none of the app's CSS, so `var()` resolves to
 * nothing under the headless renderer and cannot be interpolated by `mixOklch`
 * at all (see the guard in `color.ts`). Concrete values are not a shortcut here,
 * they are the only thing that survives a render. Users on a different palette
 * override via `KitUIProvider` or a component's `theme` prop.
 *
 * ## `radius` is the one value that flows the other way
 *
 * `globals.css` sets `--radius: 0.28rem` *so that* its `--radius-3xl` step lands
 * on this 10 — see the note beside it there. It is not drift; do not "fix" it.
 */
const defaultLightTheme: KitTheme = {
  background: "#faf9f6", // page — warm off-white
  foreground: "#141414", // text
  card: "#ffffff", // surface on the page
  cardForeground: "#141414",
  popover: "#ffffff",
  popoverForeground: "#141414",
  primary: "#1d6bff", // accent blue
  primaryForeground: "#ffffff",
  secondary: "#f2f0eb", // subtle fill
  secondaryForeground: "#141414",
  muted: "#f2f0eb",
  mutedForeground: "#6e6a63", // secondary text, leading icons
  accent: "#f2f0eb", // hover wash
  accentForeground: "#141414",
  destructive: "#d92d20",
  // `globals.css` defines no --destructive-foreground; white is the only thing
  // that reads on #d92d20, and shadcn's own default agrees.
  destructiveForeground: "#ffffff",
  border: "#d9d9d9", // hairline
  input: "#d9d9d9",
  ring: "#1d6bff",
  radius: 10,
};

const defaultDarkTheme: KitTheme = {
  background: "#0a0a0b", // page — near-black
  foreground: "#fafafa", // text
  card: "#141417", // surface, a shade above the page
  cardForeground: "#fafafa",
  popover: "#141417",
  popoverForeground: "#fafafa",
  primary: "#1d6bff", // the same accent blue in both modes
  primaryForeground: "#ffffff",
  secondary: "#1d1d21", // subtle fill
  secondaryForeground: "#fafafa",
  muted: "#1b1b1f",
  mutedForeground: "#a1a1aa", // secondary text, leading icons
  accent: "#1d1d21", // hover wash
  accentForeground: "#fafafa",
  destructive: "#f97066",
  destructiveForeground: "#fafafa",
  border: "#26272b", // hairline — separation is borders, not shadows
  input: "#26272b",
  ring: "#1d6bff",
  radius: 10,
};

interface KitThemeContextValue {
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
}

const KitThemeContext = createContext<KitThemeContextValue>({});

function useKitTheme(
  override?: Partial<KitTheme>,
  modeOverride?: "light" | "dark",
): KitTheme {
  const ctx = useContext(KitThemeContext);
  const mode = modeOverride ?? ctx.mode ?? "light";
  const base = mode === "dark" ? defaultDarkTheme : defaultLightTheme;
  return { ...base, ...ctx.theme, ...override };
}

const toRgb = converter("rgb");

const BLACK: Rgb = { mode: "rgb", r: 0, g: 0, b: 0, alpha: 1 };

/**
 * Whether to warn. Read through `globalThis`, never a bare `process`: a Vite
 * project defines no `process`, so the bare name threw a ReferenceError on the
 * very input it meant to warn about — and a stock Remotion project has no Node
 * types, so the bare name was also a type error in every install.
 */
function isDev(): boolean {
  const env = (globalThis as { process?: { env?: { NODE_ENV?: string } } })
    .process?.env;
  return env?.NODE_ENV !== "production";
}

function parseColor(c: string): Rgb {
  const s = c.trim();

  if (s.startsWith("var(")) {
    if (isDev()) {
      console.warn(
        `parseColor cannot resolve CSS variable "${s}" under Remotion's per-frame render. ` +
          "Animated colors must be concrete oklch/hex/rgb values supplied via the theme. " +
          "Falling back to the JS default.",
      );
    }
    return { ...BLACK };
  }

  const rgb = toRgb(parse(s));
  if (!rgb) {
    if (isDev()) {
      console.warn(`parseColor could not parse "${s}"; using black.`);
    }
    return { ...BLACK };
  }

  return { mode: "rgb", r: rgb.r, g: rgb.g, b: rgb.b, alpha: rgb.alpha ?? 1 };
}

/**
 * A token at partial opacity — for scrims, veils and inner washes.
 *
 * A scrim written as a literal `rgba(0,0,0,0.4)` is lit for a light surface and
 * does nothing on a dark one; `withAlpha(t.foreground, 0.4)` follows the theme
 * and a user's override. Resolves through `parseColor`, so it inherits the same
 * `var()` guard — an unresolvable token degrades to black rather than an
 * invalid colour string mid-render.
 */
function withAlpha(color: string, alpha: number): string {
  const { r, g, b } = parseColor(color);
  return formatRgb({ mode: "rgb", r, g, b, alpha });
}

export type CursorVariant = "arrow" | "dot";

export interface CursorWaypoint {
  /**
   * Frame the cursor starts travelling TOWARDS this point, on this component's
   * own clock (i.e. against `useCurrentFrame() * speed`). Absolute, not
   * relative to the previous waypoint. Waypoints are sorted by `at`; ties break
   * on array order and the last one wins.
   *
   * The FIRST waypoint has nothing to travel from, so it places the cursor
   * rather than moving it — give it an off-frame `x` to have the cursor walk in.
   */
  at: number;
  /**
   * Destination, normalized: 0 -> 1 left to right across the composition,
   * origin top-left. FRAME coordinates — a camera move inside a child
   * `<ScreenRecording>` does not move the cursor. Values outside 0-1 are legal
   * and mean off-frame, so a cursor entering from the left starts at `x: -0.1`.
   */
  x: number;
  /** Destination, normalized: 0 -> 1 top to bottom. */
  y: number;
  /**
   * Frames the travel takes. Default 14. The cursor then RESTS here until the
   * next waypoint's `at` — there is no hold field, the hold is the gap. On the
   * first waypoint there is no travel, so this is the fade-up window instead.
   */
  duration?: number;
  /**
   * Pulse a click ring on ARRIVAL, i.e. at `at + duration`. To click twice
   * without moving, add a second waypoint at the same `x`/`y`.
   */
  click?: boolean;
}

export interface CursorTrackProps {
  /**
   * What the cursor moves over — anything. Rendered full-bleed underneath it.
   * Put the `<ScreenRecording>` (or the UI sim) in here, not this inside that:
   * the cursor has to be the top layer to read as a cursor.
   */
  children?: ReactNode;
  /**
   * The path, in any order. Defaults to `DEMO_PATH` so the component is worth
   * looking at with no props; pass `[]` and it renders nothing at all, i.e. it
   * becomes a no-op wrapper.
   */
  path?: CursorWaypoint[];
  /** `arrow` (default) is a pointer; `dot` is a touch/tap puck. */
  variant?: CursorVariant;
  /**
   * Cursor height in px. Omit it and the component computes 3.9% of the
   * composition height, so it stays the size a real cursor looks at any crop.
   */
  size?: number;
  /**
   * Cursor fill. Defaults to the theme's `foreground` — so pass `mode="dark"`
   * when the recording underneath is dark, and the cursor and its outline swap
   * together.
   */
  color?: string;
  /**
   * The outline that keeps the cursor readable over arbitrary footage. Defaults
   * to the theme's `background`, the opposite end of `color`.
   */
  outlineColor?: string;
  /** The click ring. Defaults to the theme's `primary`. */
  ringColor?: string;
  /** Frames a click ring lives for. Default 14. */
  clickFrames?: number;
  /**
   * Show the cursor parked at the first waypoint before its `at`. Default
   * false — it fades in as the first move starts, which is what stops a cursor
   * sitting inertly on frame 0.
   */
  showBefore?: boolean;
  /** Design-system token overrides. */
  theme?: Partial<KitTheme>;
  mode?: "light" | "dark";
  /** Time multiplier. Every `at` is measured against `useCurrentFrame() * speed`. */
  speed?: number;
  className?: string;
}

// --- Constants -------------------------------------------------------------

/**
 * Cursor travel, and deliberately NOT the camera curve. A pointer accelerates
 * and decelerates; a camera decelerate on a cursor reads robotic. Same curve
 * the notch morph and the showcase crane already use.
 */
const CURSOR_EASE = Easing.inOut(Easing.cubic);

/** Click ring growth. Opacity fades linearly under it. */
const RING_EASE = Easing.out(Easing.cubic);

const TRAVEL_FRAMES = 14;
const CLICK_FRAMES = 14;

/** Cursor height as a fraction of the composition height, when `size` is omitted. */
const CURSOR_HEIGHT_RATIO = 0.039;

/** Ring radius at birth and at death, as multiples of the cursor height. */
const RING_START = 0.18;
const RING_END = 1.1;

/**
 * The site's own pointer (app/globals.css): a rounded arrow, ink with a rim and
 * a soft shadow, in a 24-unit box with its hotspot — the tip — at (5.5, 5.5).
 * An SVG and not an emoji or a font glyph: a glyph is whatever face the
 * renderer happens to resolve, and it would carry the hinting problems the
 * motion-quality skill is about into the one element that moves every frame.
 */
const ARROW_VIEW = 24;
const ARROW_TIP = 5.5;
/** The arrow's ink spans 14 of the 24 units; `size` is that span. */
const ARROW_INK = 14;
const ARROW_PATH = "M5.5 5.5 19 11l-5.6 1.45a2 2 0 0 0-1.45 1.45L10.5 19.5z";

/** The `dot` puck's diameter, as a multiple of the cursor height. */
const DOT_RATIO = 0.62;

/**
 * A short demo path: in from off-frame bottom-left, click, cross the frame,
 * click, then move off to the top-right. Carries the customizer preview and the
 * MCP skeleton, because `ControlType` has no array control to expose `path`
 * through — the same way `terminal-simulator` handles `lines`.
 */
const DEMO_PATH: CursorWaypoint[] = [
  { at: 0, x: -0.06, y: 0.86, duration: 6 },
  { at: 8, x: 0.34, y: 0.44, duration: 22, click: true },
  { at: 52, x: 0.68, y: 0.62, duration: 20, click: true },
  { at: 96, x: 0.82, y: 0.28, duration: 18 },
];

// --- Pure helpers (unit-tested) -------------------------------------------

export interface CursorPose {
  /** Position, normalized to the frame, origin top-left. */
  x: number;
  y: number;
  /** Click-ring progress, 0 -> 1, or 0 when no ring is up. */
  click: number;
  /** 0 before the cursor has appeared, 1 once it has. */
  opacity: number;
}

const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

/**
 * Waypoints in the order they actually play. Same-`at` ties: the later array
 * entry wins and the earlier tied entries never display, so they can never act
 * as a leg's origin — the rule `useStateTransition` already uses for `Step`.
 */
function ordered(path: CursorWaypoint[]): CursorWaypoint[] {
  return path
    .map((w, index) => ({ w, index }))
    .sort((a, b) => a.w.at - b.w.at || a.index - b.index)
    .filter((e, i, arr) => i === arr.length - 1 || arr[i + 1].w.at !== e.w.at)
    .map((e) => e.w);
}

/**
 * The cursor's pose at `frame`, folding the path forward so a waypoint that
 * starts mid-travel takes over from where the cursor actually is. Pure: same
 * frame, same answer, whatever order Remotion renders in.
 *
 * ponytail: straight-line travel. If it reads robotic, add a per-leg arc here,
 * not a prop.
 */
function cursorPoseAt(
  frame: number,
  path: CursorWaypoint[] = [],
  clickFrames: number = CLICK_FRAMES,
): CursorPose {
  const moves = ordered(path);
  if (moves.length === 0) return { x: 0.5, y: 0.5, click: 0, opacity: 0 };

  // The cursor fades up over the first waypoint's own `duration`, so a track
  // tunes its arrival without another prop. `showBefore` overrides this.
  const first = moves[0];
  const firstDur = first.duration ?? TRAVEL_FRAMES;
  const opacity =
    firstDur > 0
      ? interpolate(frame, [first.at, first.at + firstDur], [0, 1], {
          ...CLAMP,
          easing: RING_EASE,
        })
      : frame >= first.at
        ? 1
        : 0;

  // The first waypoint places the cursor — there is nothing to travel from.
  let x = first.x;
  let y = first.y;
  for (let i = 1; i < moves.length; i++) {
    const m = moves[i];
    if (frame < m.at) break;
    const dur = m.duration ?? TRAVEL_FRAMES;
    // Truncated, never blended: a leg that overruns the next move's `at` stops
    // contributing there, so the next leg starts from the pose actually on
    // screen and the cursor never averages two destinations.
    const until =
      i + 1 < moves.length ? Math.min(frame, moves[i + 1].at) : frame;
    const p =
      dur > 0
        ? interpolate(until, [m.at, m.at + dur], [0, 1], {
            ...CLAMP,
            easing: CURSOR_EASE,
          })
        : 1;
    x += (m.x - x) * p;
    y += (m.y - y) * p;
  }

  // The latest ring still alive wins, so two clicks close together do not stack
  // two circles on one point. Progress is measured from the frame AFTER the
  // click so `click === 0` reads as "no ring up" and the caller needs no second
  // flag; one frame of a 14-frame ring is not something you can see.
  let click = 0;
  if (clickFrames > 0) {
    for (const m of moves) {
      if (!m.click) continue;
      const at = m.at + (m.duration ?? TRAVEL_FRAMES);
      if (frame >= at && frame < at + clickFrames) {
        click = (frame - at + 1) / clickFrames;
      }
    }
  }

  return { x, y, click, opacity };
}

// --- Component -------------------------------------------------------------

function CursorTrackScene({
  children,
  path = DEMO_PATH,
  variant = "arrow",
  size,
  color,
  outlineColor,
  ringColor,
  clickFrames = 14,
  showBefore = false,
  theme,
  mode,
  speed = 1,
  className,
}: CursorTrackProps) {
  const frame = useCurrentFrame() * speed;
  const t = useKitTheme(theme, mode);
  const { width, height } = useVideoConfig();
  const isRendering = getRemotionEnvironment().isRendering;
  const shadowId = `cursor-shadow-${useId().replace(/:/g, "")}`;

  const h = size ?? height * CURSOR_HEIGHT_RATIO;
  const ink = color ?? t.foreground;
  const outline = outlineColor ?? t.background;
  const ring = ringColor ?? t.primary;

  const pose = cursorPoseAt(frame, path, clickFrames);
  const opacity = showBefore ? 1 : pose.opacity;
  const hidden = path.length === 0 || opacity <= 0;

  // Ring: eased radius, linear opacity. It is a circle, not type, so scaling it
  // has none of the glyph-snapping failure modes the motion-quality skill warns
  // about — and it rides the cursor, so a ring never detaches from the pointer.
  const ringRadius = interpolate(
    pose.click,
    [0, 1],
    [h * RING_START, h * RING_END],
    {
      ...CLAMP,
      easing: RING_EASE,
    },
  );
  const ringOpacity = 1 - pose.click;
  const ringStroke = Math.max(1.5, h * 0.07);

  return (
    <AbsoluteFill showInTimeline={false} className={className}>
      {children}
      {!hidden && (
        <AbsoluteFill showInTimeline={false} style={{ pointerEvents: "none" }}>
          {/* The one element that transforms every frame, so the one place
              will-change belongs — and only outside a render, where a stale
              raster is inherited across parallel tabs (motion-quality skill). */}
          <div
            style={{
              position: "absolute",
              left: 0,
              top: 0,
              opacity,
              transform: `translate(${pose.x * width}px, ${pose.y * height}px)`,
              ...(isRendering ? {} : { willChange: "transform" as const }),
            }}
          >
            {pose.click > 0 && (
              <div
                style={{
                  position: "absolute",
                  left: -ringRadius,
                  top: -ringRadius,
                  width: ringRadius * 2,
                  height: ringRadius * 2,
                  borderRadius: "50%",
                  border: `${ringStroke}px solid ${ring}`,
                  backgroundColor: withAlpha(ring, 0.12),
                  opacity: ringOpacity,
                }}
              />
            )}
            {variant === "dot" ? (
              <div
                style={{
                  position: "absolute",
                  left: (-h * DOT_RATIO) / 2,
                  top: (-h * DOT_RATIO) / 2,
                  width: h * DOT_RATIO,
                  height: h * DOT_RATIO,
                  borderRadius: "50%",
                  backgroundColor: withAlpha(ink, 0.42),
                  border: `${Math.max(1.5, h * 0.05)}px solid ${outline}`,
                }}
              />
            ) : (
              <svg
                viewBox={`0 0 ${ARROW_VIEW} ${ARROW_VIEW}`}
                width={(h * ARROW_VIEW) / ARROW_INK}
                height={(h * ARROW_VIEW) / ARROW_INK}
                style={{
                  // The hotspot is the tip, not the box's corner.
                  position: "absolute",
                  left: (-h * ARROW_TIP) / ARROW_INK,
                  top: (-h * ARROW_TIP) / ARROW_INK,
                  display: "block",
                  overflow: "visible",
                }}
              >
                <title>Pointer</title>
                <defs>
                  <filter
                    id={shadowId}
                    x="-30%"
                    y="-30%"
                    width="160%"
                    height="160%"
                  >
                    <feDropShadow
                      dx={0}
                      dy={1}
                      stdDeviation={0.8}
                      floodOpacity={0.35}
                    />
                  </filter>
                </defs>
                {/* Rim first, then the ink over it: the site cursor, stroke
                    for stroke. The rim is what carries it over footage. */}
                <g filter={`url(#${shadowId})`}>
                  <path
                    d={ARROW_PATH}
                    fill={outline}
                    stroke={outline}
                    strokeWidth={5}
                    strokeLinejoin="round"
                  />
                  <path
                    d={ARROW_PATH}
                    fill={ink}
                    stroke={ink}
                    strokeWidth={2}
                    strokeLinejoin="round"
                  />
                </g>
              </svg>
            )}
          </div>
        </AbsoluteFill>
      )}
    </AbsoluteFill>
  );
}

/* ─────────────────────────────────────────────────────────────────────────
   Remotion Studio
   ───────────────────────────────────────────────────────────────────────── */

type CursorTrackElementProps = Omit<
  ComponentProps<typeof CursorTrackScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const CursorTrackDefaults = {
  variant: "arrow",
  size: 28,
  color: "#141414",
  outlineColor: "#faf9f6",
  ringColor: "#3072db",
  clickFrames: 14,
  showBefore: false,
  speed: 1,
} satisfies Partial<CursorTrackElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const CursorTrackSchema = {
  size: {
    type: "number",
    default: 28,
    min: 12,
    max: 72,
    step: 1,
    description: "Cursor size",
    hiddenFromList: false,
    keyframable: false,
  },
  color: {
    type: "color",
    default: "#141414",
    description: "Cursor",
    keyframable: false,
  },
  outlineColor: {
    type: "color",
    default: "#faf9f6",
    description: "Outline",
    keyframable: false,
  },
  ringColor: {
    type: "color",
    default: "#3072db",
    description: "Click ring",
    keyframable: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 1,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function CursorTrackFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const { durationInFrames } = useVideoConfig();
  const left = Math.min(1, Math.max(0, (durationInFrames - 1 - frame) / 12));
  const leave = left * left;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const CursorTrackInner = forwardRef<HTMLDivElement, CursorTrackElementProps>(
  ({ style, ...props }, ref) => {
    // The layer's length, from the Sequence `wrapInSequence` puts around this.
    const { durationInFrames } = useVideoConfig();
    const rest = { ...CursorTrackDefaults, ...props };
    // The scene measures its copy once, on mount. An Inspector edit changes the
    // props without remounting it, so the key does.
    const key = JSON.stringify(props, (k, v) =>
      k === "children" ? undefined : v,
    );

    // width/height are what useVideoConfig() reports inside this Sequence, so
    // the scene lays itself out in its stage rather than the whole composition.
    // It is not a layer of its own: the one Studio shows is the wrapper's.
    return (
      <Sequence
        layout="none"
        showInTimeline={false}
        durationInFrames={durationInFrames}
        width={1280}
        height={720}
      >
        <div
          ref={ref}
          style={{
            position: "relative",
            width: 1280,
            height: 720,
            overflow: "hidden",
            color: "black",
            fontFamily: "initial",
            fontSize: 16,
            fontStyle: "normal",
            fontVariant: "normal",
            fontWeight: 400,
            fontStretch: "normal",
            fontKerning: "auto",
            fontFeatureSettings: "normal",
            fontVariationSettings: "normal",
            lineHeight: "normal",
            letterSpacing: "normal",
            wordSpacing: "normal",
            textAlign: "start",
            textIndent: 0,
            textTransform: "none",
            textShadow: "none",
            textRendering: "auto",
            whiteSpace: "normal",
            wordBreak: "normal",
            overflowWrap: "normal",
            hyphens: "manual",
            direction: "ltr",
            visibility: "visible",
            ...style,
          }}
        >
          <CursorTrackFade>
            <CursorTrackScene key={key} {...rest} />
          </CursorTrackFade>
        </div>
      </Sequence>
    );
  },
);

export const CursorTrack = Interactive.withSchema({
  Component: CursorTrackInner,
  componentName: "<CursorTrack>",
  schema: CursorTrackSchema,
  wrapInSequence: true,
});
